using System;
using System.Linq;
using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            string[] phases = {"Enter", "Hold", "Recover"};
            int[] counts = {12, 24, 16};
            float[] fps = {20, 16, 20};
            var go = new GameObject("StaggerClipValidation");
            go.hideFlags = HideFlags.HideAndDontSave;
            result.RegisterObjectCreation(go);
            var renderer = go.AddComponent<SpriteRenderer>();
            go.AddComponent<Animator>();
            Vector3 original = new Vector3(11, 17, 2);
            go.transform.position = original;
            try
            {
                for (int k = 0; k < phases.Length; k++)
                {
                    var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/05.Animation/AirBoss/AirBoss_Stagger_" + phases[k] + ".anim");
                    var bindings = AnimationUtility.GetObjectReferenceCurveBindings(clip);
                    if (bindings.Length != 1 || bindings[0].path != "" || bindings[0].propertyName != "m_Sprite" || bindings[0].type != typeof(SpriteRenderer))
                    {
                        throw new Exception("Wrong binding");
                    }

                    var keys = AnimationUtility.GetObjectReferenceCurve(clip, bindings[0]);
                    if (keys.Length != counts[k] || AnimationUtility.GetCurveBindings(clip).Length != 0 || AnimationUtility.GetAnimationEvents(clip).Length != 0)
                    {
                        throw new Exception("Unexpected keys/curves/events");
                    }

                    for (int i = 0; i < counts[k]; i++)
                    {
                        string expected = "AirBoss_Stagger_" + phases[k] + "_v03_" + i.ToString("00");
                        if (keys[i].value == null || keys[i].value.name != expected || Mathf.Abs(keys[i].time - i / fps[k]) > 0.00001f)
                        {
                            throw new Exception("Wrong reference/time " + expected);
                        }

                        clip.SampleAnimation(go, (i + 0.5f) / fps[k]);
                        if (renderer.sprite != keys[i].value || go.transform.position != original)
                        {
                            throw new Exception("Sampling failed " + expected);
                        }
                    }

                    if (Mathf.Abs(clip.length - counts[k] / fps[k]) > 0.00001f || clip.isLooping != (k == 1))
                    {
                        throw new Exception("Wrong duration/loop");
                    }

                    result.Log("PASS " + phases[k] + ": " + counts[k] + " references/times and actual sampled sprites; length=" + clip.length + "; loop=" + clip.isLooping + "; no Transform keys/events.");
                }
            }
            finally
            {
                result.DestroyObject(go);
            }
        }
    }
}
